import { useId } from "react";
import { cn } from "@/lib/utils";

/**
 * Vettly logo: two msasa leaflets forming a V. Copper (new leaf) on the left, green (mature leaf) on the right.
 * Geometry matches public/brand/*.svg (generated by scripts/generate-brand.mjs); change both together.
 */
const LEFT = "M48 84 Q50.5 35.3 10 8 Q7.5 56.7 48 84 Z";
const RIGHT = "M52 84 Q49.5 35.3 90 8 Q92.5 56.7 52 84 Z";
const LEFT_RIB = "M45 78 L20 28";
const RIGHT_RIB = "M55 78 L80 28";

const COLORS = {
  light: { left: "#C2602F", right: "#2A7D62" },
  dark: { left: "#DB7A4A", right: "#5FB08D" },
};

export function LogoMark({
  className,
  tone = "color",
  onDark = false,
  title,
}: {
  className?: string;
  tone?: "color" | "mono";
  onDark?: boolean;
  title?: string;
}) {
  const id = useId().replace(/:/g, "");
  const c = COLORS[onDark ? "dark" : "light"];
  const left = tone === "mono" ? "currentColor" : c.left;
  const right = tone === "mono" ? "currentColor" : c.right;
  return (
    <svg
      viewBox="0 0 100 88"
      className={cn("h-7 w-auto shrink-0", className)}
      role={title ? "img" : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : true}
    >
      <defs>
        <mask id={`${id}l`} maskUnits="userSpaceOnUse" x="0" y="0" width="100" height="88">
          <rect width="100" height="88" fill="#fff" />
          <path d={RIGHT} fill="#000" stroke="#000" strokeWidth="6" strokeLinejoin="round" />
          <path d={LEFT_RIB} stroke="#000" strokeWidth="2.6" strokeLinecap="round" />
        </mask>
        <mask id={`${id}r`} maskUnits="userSpaceOnUse" x="0" y="0" width="100" height="88">
          <rect width="100" height="88" fill="#fff" />
          <path d={RIGHT_RIB} stroke="#000" strokeWidth="2.6" strokeLinecap="round" />
        </mask>
      </defs>
      <path d={LEFT} fill={left} mask={`url(#${id}l)`} />
      <path d={RIGHT} fill={right} mask={`url(#${id}r)`} />
    </svg>
  );
}

/** Horizontal lockup. The wordmark is set in Public Sans Bold (loaded app-wide). */
export function Logo({
  className,
  onDark,
  tone = "color",
  markClassName,
}: {
  className?: string;
  onDark?: boolean;
  tone?: "color" | "mono";
  markClassName?: string;
}) {
  return (
    <span className={cn("inline-flex items-center gap-2.5", onDark ? "text-white" : "text-ink-900", className)}>
      <LogoMark tone={tone} onDark={onDark} className={markClassName} />
      <span className="text-[1.3125rem] leading-none font-bold tracking-[-0.02em]">Vettly</span>
    </span>
  );
}
